public static class SelfTest {
 static List<string> log=new List<string>();
 static void Assert(bool value,string name){if(!value)throw new Exception(name);log.Add("PASS "+name);}
 public static int Run(string folder) {
  Directory.CreateDirectory(folder);
  try{
   LedgerTests.Run(folder,Assert);DateTime anchor=new DateTime(2026,1,31,9,0,0);
   Assert(Logic.Occurrence(anchor,"每月",1)==new DateTime(2026,2,28,9,0,0),"Monthly short-month clamp");
   Assert(Logic.Occurrence(anchor,"每月",2)==new DateTime(2026,3,31,9,0,0),"Monthly anchor preserved after short month");
   Assert(Logic.Occurrence(new DateTime(2024,2,29,9,0,0),"每年",1)==new DateTime(2025,2,28,9,0,0),"Leap-year clamp");
   Assert(Logic.Occurrence(new DateTime(2024,2,29,9,0,0),"每年",4)==new DateTime(2028,2,29,9,0,0),"Leap-year anchor preserved");
   var state=new State();var rule=new BillRule{Name="PRIVATE-RENT",Amount=1200m,Start=anchor,Repeat="每月"};state.Rules.Add(rule);
   Logic.Generate(state,new DateTime(2026,3,1));int count=state.Bills.Count;Logic.Generate(state,new DateTime(2026,3,1));Assert(count==state.Bills.Count,"Occurrence generation idempotent");
   Bill bill=state.Bills.First();Logic.Pay(state,bill.Id,true,"");Logic.Pay(state,bill.Id,true,"");Assert(state.Entries.Count==1 && bill.Paid,"Duplicate payment cannot duplicate entries");Assert(!Logic.Ready(bill,new DateTime(2026,5,1)),"Paid bill never reminds");
   var pending=state.Bills.First(x=>!x.Paid);DateTime now=pending.Due.AddDays(-3);Assert(Logic.Ready(pending,now),"Advance notification");pending.LastNotice=now;Assert(!Logic.Ready(pending,now.AddHours(2)),"Same-day notification deduplication");pending.Snooze=now.AddHours(1);Assert(Logic.Ready(pending,now.AddHours(2)),"Explicit snooze re-notifies same day");pending.Snooze=now.AddDays(2);Assert(!Logic.Ready(pending,now.AddDays(1)),"Snooze suppresses earlier reminders");Assert(Logic.Ready(pending,now.AddDays(3)),"Overdue catch-up after restart");
   var transfer=new Entry{Amount=99m,Kind="转账",Account="银行卡",ToAccount="现金"};state.Entries.Add(transfer);Assert(state.Entries.Where(x=>x.Kind=="支出").Sum(x=>x.Amount)==1200m,"Transfers excluded from spending");
   var linkBill=new Bill{Id="link",Amount=99m,Kind="转账",Due=DateTime.Today};state.Bills.Add(linkBill);Logic.Pay(state,"link",false,transfer.Id);Assert(linkBill.EntryId==transfer.Id&&transfer.BillId=="link"&&state.Entries.Count==2,"Link existing payment without duplicate");
   Codec.SetPassword(state,"test-password-123");Assert(Codec.CheckPassword(state,"test-password-123")&&!Codec.CheckPassword(state,"wrong"),"Salted password verification");
   byte[] packed=Codec.Pack(state,"portable-backup-123");Assert(!System.Text.Encoding.UTF8.GetString(packed).Contains("PRIVATE-RENT"),"Backup hides plaintext");var decoded=Codec.Unpack(packed,"portable-backup-123");Assert(decoded.Bills.Count==state.Bills.Count&&decoded.Entries.Count==2,"Portable backup roundtrip");bool rejected=false;try{Codec.Unpack(packed,"wrong");}catch{rejected=true;}Assert(rejected,"Wrong backup password rejected");packed[50]^=1;rejected=false;try{Codec.Unpack(packed,"portable-backup-123");}catch{rejected=true;}Assert(rejected,"Tampered backup rejected before decryption");
   string storage=Path.Combine(folder,"store-"+Guid.NewGuid().ToString("N"));var store=new Store(storage);store.Change(d=>{d.Items.Add(new Item{Text="PRIVATE-NOTE"});Codec.SetPassword(d,"pass-1234");});Assert(!System.Text.Encoding.UTF8.GetString(File.ReadAllBytes(store.PathName)).Contains("PRIVATE-NOTE"),"Local file encrypted with DPAPI");Assert(new Store(storage).Data.Items[0].Text=="PRIVATE-NOTE","Local restart roundtrip");
   store.Change(d=>d.Items[0].Text="UPDATED");Assert(File.Exists(store.PathName+".previous"),"Atomic save retains previous file");Assert(Directory.GetFiles(storage,"auto-*.dat").Length==1,"Automatic daily encrypted backup");
   int before=store.Data.Items.Count;rejected=false;try{store.Change(d=>{d.Items.Add(new Item{Text="rollback"});throw new Exception("failure");});}catch{rejected=true;}Assert(rejected&&store.Data.Items.Count==before,"Failed mutation rolls back memory");
   store.Restore(decoded);Assert(Directory.GetFiles(storage,"before-restore-*.dat").Length==1,"Restore creates recovery snapshot");Assert(new Store(storage).Data.Entries.Count==2,"Restored data persists");
   var task=new Item{Text="repeat",Due=DateTime.Now.AddDays(1),Repeat="每天"};state.Items.Add(task);Logic.Complete(state,task.Id);Assert(task.Done&&state.Items.Count(x=>!x.Done&&x.Text=="repeat")==1,"Completing recurring task generates next task");Logic.Complete(state,task.Id);Assert(!task.Done,"Completed task can be restored");
   var monthTask=new Item{Text="monthly-anchor",Due=new DateTime(2096,1,31,9,0,0),Repeat="每月"};state.Items.Add(monthTask);Logic.Complete(state,monthTask.Id);var feb=state.Items.Single(x=>x.Text=="monthly-anchor"&&!x.Done);Assert(feb.Due.Value.Day==29,"Recurring task leap-month clamp");Logic.Complete(state,feb.Id);Assert(state.Items.Single(x=>x.Text=="monthly-anchor"&&!x.Done).Due.Value==new DateTime(2096,3,31,9,0,0),"Recurring task preserves original month-end anchor");
   var noLedger=new Bill{Id="no-ledger",Amount=10,Due=DateTime.Today};state.Bills.Add(noLedger);Logic.Pay(state,noLedger.Id,false,"");Assert(noLedger.Paid&&String.IsNullOrEmpty(noLedger.EntryId),"Payment can be recorded without ledger");Logic.Pay(state,noLedger.Id,true,"");int entryCount=state.Entries.Count;Logic.Pay(state,noLedger.Id,true,"");Assert(!String.IsNullOrEmpty(noLedger.EntryId)&&entryCount==state.Entries.Count,"Paid bill can be backfilled exactly once");
   string saved=store.Data.Entries.First().Id;int savedCount=store.Data.Entries.Count;using(var locked=new FileStream(store.PathName,FileMode.Open,FileAccess.Read,FileShare.None)){rejected=false;try{store.Change(d=>d.Entries.Clear());}catch{rejected=true;}Assert(rejected&&store.Data.Entries.Count==savedCount,"Save failure rolls back in-memory mutation");}Assert(new Store(storage).Data.Entries.Any(x=>x.Id==saved),"Save failure preserves original disk data");
   var dailyState=new State();TaskSchedule.Save(dailyState,null,false,"daily independent",DateTime.Today.AddHours(9),"每天",true,true);var dailyRoot=dailyState.Items.OrderBy(x=>x.Due).First();
   Assert(dailyState.Items.Any(x=>x.Due==DateTime.Today.AddDays(1).AddHours(9))&&dailyState.Items.Any(x=>x.Due==DateTime.Today.AddDays(6).AddHours(9)),"Daily tasks exist on later dates before completing today");
   int dailyCount=dailyState.Items.Count;Logic.Complete(dailyState,dailyRoot.Id);Assert(dailyState.Items.Count==dailyCount&&!dailyState.Items.Single(x=>x.Due==DateTime.Today.AddDays(1).AddHours(9)).Done,"Completing one day does not change or duplicate other dates");
   Assert(!TaskSchedule.Generate(dailyState,DateTime.Today,DateTime.Today.AddDays(30)),"Repeated task generation is idempotent");
   var deleted=dailyState.Items.Single(x=>x.Due==DateTime.Today.AddDays(2).AddHours(9));TaskSchedule.Delete(dailyState,deleted.Id);TaskSchedule.Generate(dailyState,DateTime.Today,DateTime.Today.AddDays(30));Assert(!dailyState.Items.Any(x=>x.Due==DateTime.Today.AddDays(2).AddHours(9)),"Deleting one occurrence does not recreate it on refresh");
   var edited=dailyState.Items.Single(x=>x.Due==DateTime.Today.AddDays(3).AddHours(9));TaskSchedule.Save(dailyState,edited.Id,false,"one day edited",edited.Due.Value.AddHours(1),"每天",false,false);TaskSchedule.Generate(dailyState,DateTime.Today,DateTime.Today.AddDays(30));Assert(dailyState.Items.Count(x=>x.Due.HasValue&&x.Due.Value.Date==DateTime.Today.AddDays(3))==1&&dailyState.Items.Any(x=>x.Text=="daily independent"&&x.Due==DateTime.Today.AddDays(4).AddHours(9)),"Editing one date keeps its new time and leaves other dates unchanged");
   var future=dailyState.Items.Single(x=>x.Due==DateTime.Today.AddDays(4).AddHours(9));TaskSchedule.Save(dailyState,future.Id,false,"future edited",future.Due,"每天",true,true);Assert(dailyState.Items.Any(x=>x.Text=="future edited"&&x.Due==DateTime.Today.AddDays(5).AddHours(9))&&dailyState.Items.Single(x=>x.Id==dailyRoot.Id).Done,"Editing future occurrences preserves completed history");
   var reloadedDaily=Codec.Parse(Codec.Serialize(dailyState));TaskSchedule.Generate(reloadedDaily,DateTime.Today.AddDays(40),DateTime.Today.AddDays(46));Assert(reloadedDaily.Items.Any(x=>x.Text=="future edited"&&x.Due==DateTime.Today.AddDays(46).AddHours(9)),"Series survive restart and generate a newly viewed future week");
   TaskSchedule.Stop(reloadedDaily,future.Id);int stoppedCount=reloadedDaily.Items.Count;TaskSchedule.Generate(reloadedDaily,DateTime.Today.AddDays(60),DateTime.Today.AddDays(66));Assert(reloadedDaily.Items.Count==stoppedCount,"Stopping a series prevents future regeneration");
   var legacyState=new State();legacyState.Items.Add(new Item{Text="legacy daily",Due=DateTime.Today.AddHours(8),Repeat="每天"});TaskSchedule.Generate(legacyState,DateTime.Today,DateTime.Today.AddDays(6));Assert(legacyState.TaskSeries.Count==1&&legacyState.Items.Count==7&&legacyState.Items.All(x=>!String.IsNullOrEmpty(x.SeriesId)),"Old daily items migrate to independent daily occurrences");
   var monthlyState=new State();monthlyState.TaskSeries.Add(new TaskSeries{Text="month end",Start=new DateTime(2096,1,31,9,0,0),Repeat="每月"});TaskSchedule.Generate(monthlyState,new DateTime(2096,1,1),new DateTime(2096,3,31));Assert(monthlyState.Items.Any(x=>x.Due==new DateTime(2096,2,29,9,0,0))&&monthlyState.Items.Any(x=>x.Due==new DateTime(2096,3,31,9,0,0)),"Independent monthly occurrences preserve leap-month and month-end anchors");
   var oldWeek=new State();TaskSchedule.Save(oldWeek,null,false,"original schedule",DateTime.Today.AddHours(8),"每天",false,true);TaskSchedule.Generate(oldWeek,DateTime.Today.AddDays(45),DateTime.Today.AddDays(45));var revision=oldWeek.Items.Single(x=>x.Due==DateTime.Today.AddDays(45).AddHours(8));TaskSchedule.Save(oldWeek,revision.Id,false,"revised schedule",revision.Due,"每天",false,true);TaskSchedule.Generate(oldWeek,DateTime.Today.AddDays(35),DateTime.Today.AddDays(36));Assert(oldWeek.Items.Where(x=>x.Due>=DateTime.Today.AddDays(35)&&x.Due<DateTime.Today.AddDays(37)).All(x=>x.Text=="original schedule"),"Future edits do not rewrite earlier weeks that were not previously generated");
   var febEdit=monthlyState.Items.Single(x=>x.Due==new DateTime(2096,2,29,9,0,0));TaskSchedule.Save(monthlyState,febEdit.Id,false,"edited month end",febEdit.Due,"每月",true,true);TaskSchedule.Generate(monthlyState,new DateTime(2096,2,1),new DateTime(2096,3,31));Assert(monthlyState.Items.Any(x=>x.Text=="edited month end"&&x.Due==new DateTime(2096,3,31,9,0,0)),"Editing a February occurrence keeps the original monthly anchor");
   var bounded=new State();DateTime boundedStart=DateTime.Today.AddHours(9),boundedEnd=boundedStart.AddDays(2);TaskSchedule.Save(bounded,null,false,"bounded daily",boundedStart,"每天",false,true,boundedEnd);TaskSchedule.Generate(bounded,DateTime.Today,DateTime.Today.AddDays(60));Assert(bounded.Items.Count==3&&bounded.Items.Any(x=>x.Due==boundedEnd)&&bounded.Items.All(x=>x.Due<=boundedEnd),"Repeat cutoff includes the final occurrence and prevents later generation");
   var finalOccurrence=bounded.Items.Single(x=>x.Due==boundedEnd);Assert(TaskSchedule.CanRemind(bounded,finalOccurrence,boundedEnd.AddSeconds(30))&&!TaskSchedule.CanRemind(bounded,finalOccurrence,boundedEnd.AddMinutes(1)),"Final cutoff minute can remind; expired repeat cannot remind again");
   var boundedReload=Codec.Parse(Codec.Serialize(bounded));TaskSchedule.Generate(boundedReload,DateTime.Today.AddDays(60),DateTime.Today.AddDays(70));Assert(boundedReload.Items.Count==3&&boundedReload.TaskSeries.Single().RepeatEnd==boundedEnd,"Repeat cutoff survives restart and later calendar browsing");
   bool rejectedCutoff=false;try{TaskSchedule.Save(new State(),null,false,"invalid cutoff",boundedStart,"每天",false,true,boundedStart.AddMinutes(-1));}catch{rejectedCutoff=true;}Assert(rejectedCutoff,"Repeat cutoff before first reminder is rejected");
   var shortened=new State();TaskSchedule.Save(shortened,null,false,"shorten repeat",boundedStart,"每天",false,true);var shortenRoot=shortened.Items.Single(x=>x.Due==boundedStart);TaskSchedule.Save(shortened,shortenRoot.Id,false,"shorten repeat",boundedStart,"每天",false,true,boundedEnd);Assert(shortened.Items.Count==3&&shortened.Items.All(x=>x.Due<=boundedEnd),"Setting a cutoff removes previously generated pending dates after it");
   var weeklyEnd=new State();TaskSchedule.Save(weeklyEnd,null,false,"weekly cutoff",boundedStart,"每周",false,true,boundedStart.AddDays(10));TaskSchedule.Generate(weeklyEnd,DateTime.Today,DateTime.Today.AddDays(60));Assert(weeklyEnd.Items.Count==2,"Weekly repetition also respects cutoff between occurrences");
   Assert(TaskSchedule.EditorTime(new DateTime(2026,10,21,14,37,59),null,null)==new DateTime(2026,10,21,14,37,0),"New task defaults to current date, hour and minute");
   Assert(TaskSchedule.EditorTime(new DateTime(2026,10,21,14,37,59),new DateTime(2026,10,25),null)==new DateTime(2026,10,25,14,37,0),"Adding on a calendar day keeps that day and uses current time");
   Assert(Logic.CsvCell("=SUM(A1)").StartsWith("\"'="),"CSV formula injection mitigated");
   Assert(Weather.Parse("{\"current\":{\"temperature_2m\":21.6,\"weather_code\":3}}")=="22°C · 多云","Weather response decodes actual temperature and condition");rejected=false;try{Weather.Parse("{\"current\":{\"temperature_2m\":null,\"weather_code\":null}}");}catch{rejected=true;}Assert(rejected,"Missing weather data cannot display a fake zero temperature");
   File.WriteAllLines(Path.Combine(folder,"self-test.txt"),log);return 0;
  }catch(Exception e){log.Add("FAIL "+e);File.WriteAllLines(Path.Combine(folder,"self-test.txt"),log);return 1;}
 }
}
public static partial class RenderTest {
 static System.Collections.Generic.IEnumerable<T> Find<T>(DependencyObject root) where T:DependencyObject {if(root is T)yield return (T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Find<T>(VisualTreeHelper.GetChild(root,i)))yield return child;}
 static void Click(Window w,string text){w.UpdateLayout();var b=Find<System.Windows.Controls.Button>(w).First(x=>Convert.ToString(x.Content)==text);b.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));}
 static void Modal(DeskApp app,Action open,Action<Window> fill) {
  Exception error=null;bool entered=false;
  app.Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.ApplicationIdle,new Action(()=>{Window dialog=null;try{dialog=app.Windows.Cast<Window>().Last(x=>x.IsVisible&&x!=app.Panel&&x!=app.Finance);entered=true;fill(dialog);}catch(Exception e){error=e;if(dialog!=null)dialog.Close();}}));
  open();if(error!=null)throw error;if(!entered)throw new Exception("Editor did not open");
 }
 static System.Windows.Controls.StackPanel Fields(Window w){return (System.Windows.Controls.StackPanel)((System.Windows.Controls.ScrollViewer)w.Content).Content;}
 static void Require(bool test,string name,System.Collections.Generic.List<string> report){if(!test)throw new Exception(name);report.Add("PASS "+name);}
