    Click(app.Panel,"高优");Require(Find<System.Windows.Controls.TextBlock>(app.Panel).Any(x=>x.Text.Contains("UI-created task"))&&!Find<System.Windows.Controls.TextBlock>(app.Panel).Any(x=>x.Text=="整理本周的项目资料"),"High-priority filter excludes regular tasks",report);Click(app.Panel,"全部");
    var taskText=Find<System.Windows.Controls.TextBlock>(app.Panel).Single(x=>x.Text.Contains("UI-created task"));var taskRow=(System.Windows.Controls.DockPanel)((System.Windows.Controls.StackPanel)taskText.Parent).Parent;Find<System.Windows.Controls.CheckBox>(taskRow).Single().RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Require(app.Store.Data.Items.Single(x=>x.Text=="UI-created task").Done,"Weekly task checkbox persists completion",report);
    taskText=Find<System.Windows.Controls.TextBlock>(app.Panel).Single(x=>x.Text.Contains("UI-created task"));taskRow=(System.Windows.Controls.DockPanel)((System.Windows.Controls.StackPanel)taskText.Parent).Parent;Find<System.Windows.Controls.CheckBox>(taskRow).Single().RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Require(!app.Store.Data.Items.Single(x=>x.Text=="UI-created task").Done,"Weekly task checkbox supports undo",report);
    Modal(app,()=>app.Settings(),w=>{Capture(w,Path.Combine(folder,"settings-theme.png"));var preset=Find<System.Windows.Controls.Button>(w).First(b=>b.Content is System.Windows.Controls.StackPanel&&Find<System.Windows.Controls.TextBlock>((DependencyObject)b.Content).Any(t=>t.Text=="晨雾米白"));preset.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Require(app.Store.Data.Settings.SurfaceColor=="#F7FAFC","Theme preset saves actual panel colors",report);((SettingsWindow)w).SelectPage(1);var sliders=Find<System.Windows.Controls.Slider>(w).ToList();sliders[0].Value=.4;sliders[1].Value=.8;Require(Math.Abs(app.Panel.Opacity-.8)<.01,"Settings sliders preview overall opacity immediately",report);app.Panel.Refresh();Require(Math.Abs(app.Panel.Opacity-.8)<.01,"Periodic refresh does not cancel active transparency preview",report);Capture(w,Path.Combine(folder,"appearance.png"));((SettingsWindow)w).SelectPage(3);var seconds=Find<System.Windows.Controls.CheckBox>(w).First();seconds.IsChecked=false;Require(!app.Store.Data.Settings.ShowSeconds,"Clock control persists setting",report);for(int page=2;page<7;page++){((SettingsWindow)w).SelectPage(page);Capture(w,Path.Combine(folder,"settings-tab-"+page+".png"));}w.Close();});Require(Math.Abs(app.Store.Data.Settings.Opacity-.8)<.01&&Math.Abs(app.Panel.Opacity-.8)<.01,"Closing settings flushes and keeps auto-saved transparency",report);Require(new Store(app.Store.Folder).Data.Settings.SurfaceColor=="#F7FAFC","Theme survives data reload",report);
    Modal(app,()=>Click(app.Panel,"专注番茄"),w=>{Capture(w,Path.Combine(folder,"dialog-focus.png"));Click(w,"开始 / 继续");});Require(Find<System.Windows.Controls.Button>(app.Panel).Any(x=>Convert.ToString(x.Content).StartsWith("专注 ")),"Pomodoro starts a real countdown",report);
    Modal(app,()=>{Find<System.Windows.Controls.Button>(app.Panel).First(x=>Convert.ToString(x.Content).StartsWith("专注 ")).RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));},w=>Click(w,"重置为25分钟"));
    Modal(app,()=>Click(app.Panel,"☀"),w=>{Capture(w,Path.Combine(folder,"dialog-weather.png"));w.Close();});
    Modal(app,()=>{app.Unlocked=false;if(!app.Unlock())throw new Exception("Unlock was cancelled");},w=>{Find<System.Windows.Controls.PasswordBox>(w).First().Password="render-test-password";Capture(w,Path.Combine(folder,"dialog-unlock.png"));Click(w,"解锁");});Require(app.Unlocked,"Dark unlock dialog accepts correct password",report);
    Modal(app,()=>typeof(DeskApp).GetMethod("BackupPassword",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(app,new object[]{true}),w=>{foreach(var password in Find<System.Windows.Controls.PasswordBox>(w))password.Password="backup-preview-password";Capture(w,Path.Combine(folder,"dialog-backup.png"));Click(w,"继续");});
    Modal(app,()=>{if(UI.Message("这是界面测试提示，不会修改数据。","确认操作",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.No)throw new Exception("Confirmation returned unexpected result");},w=>{Capture(w,Path.Combine(folder,"dialog-confirm.png"));Click(w,"否");});Require(true,"Dark confirmation preserves explicit negative response",report);
    Capture(app.Panel,Path.Combine(folder,"desktop.png"));Capture(app.Finance,Path.Combine(folder,"finance.png"));
    app.Panel.Width=440;app.Panel.Height=620;Capture(app.Panel,Path.Combine(folder,"desktop-compact.png"));app.Panel.Width=500;app.Panel.Height=820;
    Require(!Find<System.Windows.Controls.TextBlock>(app.Panel).Any(x=>x.Text.Contains("房租")||x.Text.Contains("2400")),"Desktop does not expose private bill name or amount",report);
    var editor=UI.Window("private-test");app.Track(editor);editor.Show();
    app.Lock();if(app.Unlocked || app.PrivateWindows.Count>0)throw new Exception("Lock did not close private windows");
    report.Add("PASS WPF panel and all finance tabs rendered");report.Add("PASS Lock closes finance and private editors");File.WriteAllLines(Path.Combine(folder,"render-test.txt"),report);
   }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"render-test.txt"),"FAIL "+ex);Environment.ExitCode=1;}
   finally {app.Exiting=true;app.Panel.Close();app.Shutdown();}
  }));app.Run();
 }
 static void Capture(Window w,string path){w.UpdateLayout();var pendingFrame=new System.Windows.Threading.DispatcherFrame();w.Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.ContextIdle,new Action(()=>pendingFrame.Continue=false));System.Windows.Threading.Dispatcher.PushFrame(pendingFrame);w.UpdateLayout();var bitmap=new RenderTargetBitmap((int)w.ActualWidth,(int)w.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(w);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(path))encoder.Save(f);}
}
public static class SmokeTest {
 public static void Run(string folder) {
  Directory.CreateDirectory(folder);var app=new DeskApp();DeskApp.CurrentApp=app;UI.InstallTheme(app);app.ShutdownMode=ShutdownMode.OnExplicitShutdown;
  app.DispatcherUnhandledException+=(s,e)=>{File.WriteAllText(Path.Combine(folder,"smoke-test.txt"),"FAIL "+e.Exception);e.Handled=true;app.Exiting=true;app.Shutdown(1);};
  app.Exit+=(s,e)=>app.Cleanup();
  app.Startup+=(sender,args)=>{
   var report=new List<string>();
   Action<bool,string> check=(test,name)=>{if(!test)throw new Exception(name);report.Add("PASS "+name);};
   try {
    string smokeFolder=Path.Combine(folder,"smoke-store-"+Guid.NewGuid().ToString("N"));var initial=new Store(smokeFolder);initial.Change(d=>d.Settings.Hotkey=0x4C);app.Start(smokeFolder);
    check(app.Panel.IsVisible&&!app.Unlocked,"Production startup creates panel with finance locked");
    app.Toggle();check(!app.Panel.IsVisible,"Tray toggle hides panel");app.Toggle();check(app.Panel.IsVisible,"Tray toggle restores panel");
    app.Store.Change(d=>{Codec.SetPassword(d,"smoke-password");d.Rules.Add(new BillRule{Name="SMOKE PRIVATE",Amount=25,Repeat="不重复",Start=DateTime.Today.AddDays(-1).AddHours(9)});d.Items.Add(new Item{Text="SMOKE TASK",Due=DateTime.Now.AddHours(-2)});d.Settings.PauseUntil=DateTime.Now.AddHours(1);});
    app.Tick();check(app.Store.Data.Bills.Count==1&&!app.Store.Data.Bills[0].LastNotice.HasValue,"Paused scheduler generates bills without sending reminders");
    app.Store.Change(d=>d.Settings.PauseUntil=null);app.Tick();check(app.Store.Data.Bills[0].LastNotice.HasValue&&app.Store.Data.Items[0].LastNotice.HasValue,"Production reminder scheduler catches up both tasks and bills");
    DateTime notice=app.Store.Data.Bills[0].LastNotice.Value;app.Tick();check(app.Store.Data.Bills[0].LastNotice==notice,"Repeated scheduler tick does not duplicate same-day reminder");
    app.Store.Change(d=>{d.Settings.EnableReminders=false;d.Items.Add(new Item{Text="Disabled reminder regression",Due=DateTime.Now.AddMinutes(-1)});});app.Tick();check(!app.Store.Data.Items.Single(x=>x.Text=="Disabled reminder regression").LastNotice.HasValue,"Disabled reminders do not consume a due task notice");
    app.Store.Change(d=>d.Settings.EnableReminders=true);app.Tick();check(app.Store.Data.Items.Single(x=>x.Text=="Disabled reminder regression").LastNotice.HasValue,"Re-enabling reminders catches up due tasks");
    app.Unlocked=true;app.LastInput=DateTime.Now;app.OpenFinance();check(app.Finance!=null&&app.Finance.IsVisible,"Production finance window opens when unlocked");
    app.LastInput=DateTime.Now.AddMinutes(-6);app.Tick();check(!app.Unlocked&&app.Finance==null&&app.PrivateWindows.Count==0,"Production idle timer locks and closes finance");
    DateTime reminderDay=DateTime.Today.AddDays(1).AddHours(9);app.Store.Change(d=>TaskSchedule.Save(d,null,false,"Independent daily reminder",reminderDay,"每天",false,true));app.Tick(reminderDay);check(app.Store.Data.Items.Single(x=>x.Text=="Independent daily reminder"&&x.Due==reminderDay).LastNotice==reminderDay,"First daily occurrence sends its scheduled reminder");app.Tick(reminderDay.AddDays(1));check(app.Store.Data.Items.Single(x=>x.Text=="Independent daily reminder"&&x.Due==reminderDay.AddDays(1)).LastNotice==reminderDay.AddDays(1)&&!app.Store.Data.Items.Single(x=>x.Text=="Independent daily reminder"&&x.Due==reminderDay).Done,"Tomorrow reminds independently even when yesterday remains incomplete");
    DateTime lastReminder=reminderDay.AddDays(3);app.Store.Change(d=>TaskSchedule.Save(d,null,false,"Cutoff scheduler regression",lastReminder,"每天",false,true,lastReminder));app.Tick(lastReminder.AddSeconds(20));check(app.Store.Data.Items.Single(x=>x.Text=="Cutoff scheduler regression").LastNotice==lastReminder.AddSeconds(20),"Cutoff minute receives its final scheduled reminder");app.Tick(lastReminder.AddDays(1));check(app.Store.Data.Items.Count(x=>x.Text=="Cutoff scheduler regression")==1&&app.Store.Data.Items.Single(x=>x.Text=="Cutoff scheduler regression").LastNotice==lastReminder.AddSeconds(20),"After cutoff scheduler neither creates another task nor re-notifies overdue occurrence");
    string corrupt=Path.Combine(folder,"corrupt-store-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(corrupt);File.WriteAllText(Path.Combine(corrupt,"desk.dat"),"damaged");bool rejected=false;try{new Store(corrupt);}catch{rejected=true;}check(rejected&&File.ReadAllText(Path.Combine(corrupt,"desk.dat"))=="damaged","Corrupt primary rejected without overwrite");
    var recovery=new Store(corrupt,true);recovery.Restore(app.Store.Data);check(new Store(corrupt).Data.Bills.Count==1&&Directory.GetFiles(corrupt,"before-restore-*.dat").Length==1,"Recovery saves damaged original before restoring snapshot");
    File.WriteAllLines(Path.Combine(folder,"smoke-test.txt"),report);app.Quit();
   } catch(Exception e){report.Add("FAIL "+e);File.WriteAllLines(Path.Combine(folder,"smoke-test.txt"),report);app.Exiting=true;app.Shutdown(1);}
  };app.Run();
 }
}
